-- Import only the workbook-labelled verified property register, separately from its operational logs.
-- Capacity is retained as source information, not occupied-room or support-delivery evidence.
-- Existing records and notes remain untouched. A property default status is its Hub listing state.
insert into properties (company_id, ref, name, address_line1, city, postcode, notes)
select c.id, s.ref, s.name, s.name, 'Birmingham', s.postcode, s.notes
from companies c
cross join (values
