) s(ref, name, postcode, notes)
where c.code = 'VH' and not exists (
 select 1 from properties p where p.company_id = c.id and (
 upper(p.ref) = upper(s.ref) or (
 regexp_replace(upper(p.postcode), '[^A-Z0-9]', '', 'g') = regexp_replace(upper(s.postcode), '[^A-Z0-9]', '', 'g') and (
 regexp_replace(lower(split_part(p.address_line1, ',', 1)), '[^a-z0-9]', '', 'g') = regexp_replace(lower(s.name), '[^a-z0-9]', '', 'g') or
 regexp_replace(lower(split_part(p.name, ',', 1)), '[^a-z0-9]', '', 'g') = regexp_replace(lower(s.name), '[^a-z0-9]', '', 'g')))))
on conflict (company_id, ref) do nothing;
